const stories=storyRows.map(([id,title,category,hook,roles,acts,outcomes,history,source,route])=>({id,title,category,hook,roles,acts,outcomes,history,source,route,period:category==='Repères futurs'?'future':'1889'}));
function storyEscape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function showStories(){show('stories');renderStories();}
function renderStories(){
 const wasDetail=!document.getElementById('storyDetail').hidden;
 const norm=s=>String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const query=norm(document.getElementById('storySearch').value.trim()),category=document.getElementById('storyCategory').value,period=document.getElementById('storyPeriod').value;
 const matches=stories.filter(s=>(!category||s.category===category)&&(!period||s.period===period)&&norm([s.title,s.hook,s.roles,s.history,s.acts.flat().join(' ')].join(' ')).includes(query));
 document.getElementById('storyDetail').hidden=true;document.getElementById('storyList').hidden=false;
 document.getElementById('storyCount').textContent=`${matches.length} / ${stories.length} trames · préparation libre, sans résultat automatique`;
 document.getElementById('storyList').innerHTML=matches.length?matches.map(s=>`<button class="story-card" onclick="openStory('${s.id}')"><span class="cat-badge">${s.category}</span><strong>${s.title}</strong><span>${s.hook}</span><small>${s.period==='future'?'Hors jeu en 1889':'3 temps de jeu · durée libre'}</small></button>`).join(''):'<p>Aucune trame trouvée. Essaye un thème ou un mot plus simple.</p>';
 if(wasDetail)document.getElementById('storyList').scrollIntoView({block:'start'});
}
function openStory(id){
 const s=stories.find(s=>s.id===id);if(!s)return;
 document.getElementById('storyList').hidden=true;
 const detail=document.getElementById('storyDetail');detail.hidden=false;
 const source=storySources[s.source];
 detail.innerHTML=`<article class="story-article"><div class="story-detail-heading"><button class="secondary" onclick="renderStories()">Retour aux trames</button><span class="cat-badge">${s.category}</span></div><h2>${s.title}</h2><p class="story-hook">${s.hook}</p><div class="route-note">${s.period==='future'?'Repère hors jeu en 1889. Ne pas utiliser cette découverte comme soin disponible.':'Préparer avec les joueurs : accord sur le thème, droit de refuser, évolution et issue choisies ensemble. Une nouveauté ne garantit ni succès ni complication.'}</div><p><b>Rôles :</b> ${s.roles}</p><div class="story-quick"><b>Pour lancer en une phrase</b><p>${s.acts[0][3]}</p></div><h3>Trois temps possibles</h3>${s.acts.map(([title,action,gesture,phrase],index)=>`<section class="story-act"><h3>${index+1}. ${title}</h3><p>${action}</p><div class="rp-gesture"><b>Geste RP</b><span>${gesture}</span></div><p class="story-phrase">→ ${phrase}</p></section>`).join('')}<section class="section"><h3>Issues ouvertes, à choisir ensemble</h3><p>${s.outcomes}</p><p>Le joueur concerné décrit ses sensations et son évolution. Refuser ou interrompre un essai n’impose aucune punition médicale.</p></section><details class="story-history"><summary>Repère historique et limites</summary><p>${s.history}</p>${source?`<a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.title}</a>`:'<p>Scénario inventé pour le RP, pas un événement historique attesté.</p>'}</details><div class="scene-tools">${s.route?`<button class="next" onclick="start('${s.route}')">Ouvrir un soin guidé si nécessaire</button>`:''}<button class="secondary" onclick="renderStories()">Retour au catalogue</button></div><small>Pas de dose, recette, protocole expérimental réel, maladie forcée ou enregistrement.</small></article>`;
 detail.scrollIntoView({block:'start'});detail.querySelector('h2').setAttribute('tabindex','-1');detail.querySelector('h2').focus({preventScroll:true});
}
document.addEventListener('DOMContentLoaded',()=>{
 const select=document.getElementById('storyCategory');[...new Set(stories.map(s=>s.category))].sort((a,b)=>a.localeCompare(b,'fr')).forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;select.append(option);});
});
